import app from 'flarum/common/app';
import Model from 'flarum/common/Model';
/**
 * A member's trust level and progress, the `trust-levels` JSON:API type
 * (id = the member's user id). Only the member and staff can load it.
 */
export default class TrustLevel extends Model {
  progress() {
    return this.data.attributes;
  }
}

/** The member's progress, from the API (once per call: it moves as they read and post). */
export function loadProgress(userId, errorHandler) {
  return app.store.find('trust-levels', userId, {}, errorHandler ? {
    errorHandler
  } : {}).then(model => model.progress());
}

/** Staff: change a member's level, lock, note or hold; answers with the progress after it. */
export function saveProgress(userId, attributes) {
  const model = app.store.getById('trust-levels', userId) || app.store.createRecord('trust-levels', {
    type: 'trust-levels',
    id: userId
  });
  model.exists = true;
  return model.save(attributes).then(saved => saved.progress());
}
flarum.reg.add('ernestdefoe-trust-levels', 'common/TrustLevel', TrustLevel);